  if(ch>0){// turns late and chases, trailing
   const p=pathP(t),q=bez(Math.max(0,p-.2)),tg:[number,number]=[q[0]+.9,q[1]+1.2],d=sm(T.burst+.35,T.shot+.3,t,x=>x*(1.3-.3*x));
   u=lerp(u,tg[0],d*.85);v=lerp(v,tg[1],d*.85);pose=blendPose(pose,runCycle((t-T.burst)*runCadence(.8),{speed:.8}),ch);yaw=lerpAng(yaw,Math.atan2(tg[1]-v,tg[0]-u),ch);}
