function ballDir(st:Stage,fr:Frame,O:Drib,t:number){const a=O.ball(t-.05),b=O.ball(t),p=fp(st,fr,a.u,a.v,a.y),q=fp(st,fr,b.u,b.v,b.y);return Math.atan2(q[1]-p[1],q[0]-p[0]);}
