const C1={ko:A(0,'The 2024'),uzb:A(0,'in Uzbekistan'),play:A(0,'France play'),r16:A(0,'round of sixteen'),abd:A(0,'Abdessamad Mohammed'),sets:A(0,'sets up'),tou:A(0,'Mamadou Touré'),scores:A(0,'he scores'),win:A(0,'France win'),ft:A(0,'five two'),end:AUTH[0].seconds};
